@CrossOrigin
@RestController
@RequestMapping("/ConditionQuery")
public class ConditionQueryRestController extends BaseSpringRestController {
	
	public ConditionQueryRestController( ConditionService service ) {
        this.service = service;
    }
    
    /**
     * Handles loading a Condition using a UUID
     * @param		UUID conditionId
     * @return		Condition
     */    
    @GetMapping("/load")
    public Condition load( @RequestParam(required=true) UUID conditionId ) {
    	Condition entity = null;

    	try {  
    		entity = service.getCondition( new ConditionFetchOneSummary( conditionId ) );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Condition using Id " + conditionId );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Condition business objects
     * @return		Set<Condition>
     */
    @GetMapping("/")
    public List<Condition> loadAll() {                
    	List<Condition> conditionList = null;
        
    	try {
            // load the Condition
            conditionList = service.getAllCondition();
            
            if ( conditionList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Conditions" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Conditions ", exc );
        	return null;
        }

        return conditionList;
                            
    }



//************************************************************************    
// Attributes
//************************************************************************
    protected Condition condition = null;
    protected ConditionService service = null;
    private static final Logger LOGGER = Logger.getLogger(ConditionQueryRestController.class.getName());
    
}
